#include <filesystem>
#include <fstream>
#include <sstream>
#include <iostream>
#include <string>
#include <set>
#include <cstdint>
namespace fs=std::filesystem;
std::uint64_t available(const fs::path& p){std::ifstream f(p);std::string l;std::getline(f,l);std::getline(f,l);std::istringstream s(l);std::string device;std::uint64_t total,used,avail;if(!(s>>device>>total>>used>>avail))throw std::runtime_error("quota parse");return avail;}
int main(int argc,char**argv){try{if(argc!=3)return 2;fs::path a=argv[1],h=argv[2];std::ifstream f(a/"COHORT.tsv");std::string l;std::getline(f,l);std::uint64_t bytes=0;std::set<std::string> names;while(std::getline(f,l)){std::istringstream s(l);std::string b,full,n;std::getline(s,b,'\t');std::getline(s,full,'\t');std::getline(s,n,'\t');if(n.empty()||n.find('/')!=n.npos||!names.insert(n).second)throw std::runtime_error("cohort identity");auto src=h/n/"source.tar.gz";if(fs::exists(src)||fs::is_symlink(src))throw std::runtime_error("original still present "+n);if(!fs::is_regular_file(h/n/"ARCHIVED_SOURCE.json"))throw std::runtime_error("index missing "+n);if(fs::file_size(a/"payload"/n/"source.tar.gz")!=std::stoull(b))throw std::runtime_error("copy size");bytes+=std::stoull(b);}if(names.size()!=59||bytes!=10847851056ULL)throw std::runtime_error("cohort totals");std::ifstream j(a/"REMOVAL_JOURNAL.tsv");std::set<std::string> intents,done;std::getline(j,l);while(std::getline(j,l)){std::istringstream s(l);std::string st,n;std::getline(s,st,'\t');std::getline(s,n,'\t');if(st=="INTENT"){if(!intents.insert(n).second)throw std::runtime_error("duplicate intent");}else if(st=="REMOVED_AND_INDEXED"){if(!done.insert(n).second)throw std::runtime_error("duplicate done");}else throw std::runtime_error("journal state");}if(intents!=names||done!=names)throw std::runtime_error("journal cohort mismatch");auto before=available(a/"QUOTA_BEFORE.txt"),after=available(a/"QUOTA_AFTER.txt");std::cout<<"removed_source_count\t"<<names.size()<<"\nremoved_source_logical_bytes\t"<<bytes<<"\nquota_available_before_bytes\t"<<before<<"\nquota_available_after_bytes\t"<<after<<"\nquota_available_delta_bytes\t";if(after>=before)std::cout<<after-before;else std::cout<<'-'<<before-after;std::cout<<"\njournal_and_index_audit\tPASS\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
